Step 2: Set up OpenSearch Service indexes
Create two OpenSearch Service indexes: one for vector embeddings (k-NN) and one for text metadata. This architecture supports semantic search and hybrid queries.
from opensearchpy import OpenSearch, RequestsHttpConnection
from requests_aws4auth import AWS4Auth
import boto3
session = boto3.Session()
credentials = session.get_credentials()
awsauth = AWS4Auth(
credentials.access_key,
credentials.secret_key,
session.region_name,
'es',
session_token=credentials.token
)
opensearch_client = OpenSearch(
hosts=[{'host': 'YOUR_OPENSEARCH_ENDPOINT', 'port': 443}],
http_auth=awsauth,
use_ssl=True,
verify_certs=True,
connection_class=RequestsHttpConnection
)
# Create k-Nearest Neighbors (k-NN) index for embeddings
knn_index_body = {
"settings": {
"index.knn": True,
"number_of_shards": 2,
"number_of_replicas": 1
},
"mappings": {
"properties": {
"video_id": {"type": "keyword"},
"segment_index": {"type": "integer"},
"timestamp": {"type": "float"},
"embedding": {
"type": "knn_vector",
"dimension": 1024,
"method": {
"name": "hnsw",
"space_type": "cosinesimilarity",
"engine": "faiss"
}
},
"s3_uri": {"type": "keyword"}
}
}
}
opensearch_client.indices.create(
index="video-embeddings-knn",
body=knn_index_body
)
# Create text index for metadata
text_index_body = {
"settings": {
"number_of_shards": 2,
"number_of_replicas": 1
},
"mappings": {
"properties": {
"video_id": {"type": "keyword"},
"segment_index": {"type": "integer"},
"tags": {"type": "text", "analyzer": "standard"}
}
}
}
opensearch_client.indices.create(
index="video-embeddings-text",
body=text_index_body
)
Step 3: Process videos with Nova Multimodal Embeddings
The Amazon Bedrock async API processes videos and generates embeddings. It segments videos into 15-second chunks and combines audio and visual information.
import boto3
import json
import time
bedrock = boto3.client('bedrock-runtime', region_name='us-east-1')
def generate_video_embeddings(video_s3_uri, output_s3_uri):
"""Generate embeddings for a video using Nova MME async API."""
# Start async job
response = bedrock.start_async_invoke(
modelId="amazon.nova-2-multimodal-embeddings-v1:0",
modelInput={
"taskType": "SEGMENTED_EMBEDDING",
"segmentedEmbeddingParams": {
"embeddingPurpose": "GENERIC_INDEX",
"embeddingDimension": 1024,
"video": {
"format": "mp4",
"embeddingMode": "AUDIO_VIDEO_COMBINED",
"source": {"s3Location": {"uri": video_s3_uri}},
"segmentationConfig": {"durationSeconds": 15}
}
}
},
outputDataConfig={"s3OutputDataConfig": {"s3Uri": output_s3_uri}}
)
# Poll for completion
invocation_arn = response["invocationArn"]
while True:
job = bedrock.get_async_invoke(invocationArn=invocation_arn)
if job["status"] == "Completed":
return read_embeddings_from_s3(job["outputDataConfig"]["s3OutputDataConfig"]["s3Uri"])
elif job["status"] in ["Failed", "Expired"]:
raise RuntimeError(f"Job failed: {job.get('failureMessage')}")
time.sleep(10)
def manage_concurrent_jobs(bedrock_client, video_queue, max_concurrent=30):
"""Manage 30 concurrent async jobs within quota limits."""
active_jobs = {}
while video_queue or active_jobs:
# Submit new jobs up to limit (uses same start_async_invoke call as above)
while len(active_jobs) < max_concurrent and video_queue:
video_info = video_queue.pop(0)
response = bedrock_client.start_async_invoke(
modelId="amazon.nova-2-multimodal-embeddings-v1:0",
modelInput={...}, # Same model_input structure as generate_video_embeddings()
outputDataConfig={"s3OutputDataConfig": {"s3Uri": video_info['output_uri']}}
)
active_jobs[response["invocationArn"]] = video_info
# Poll all active jobs
for arn in list(active_jobs.keys()):
job = bedrock_client.get_async_invoke(invocationArn=arn)
if job["status"] == "Completed":
video_info = active_jobs.pop(arn)
embeddings = read_embeddings_from_s3(job["outputDataConfig"]["s3OutputDataConfig"]["s3Uri"])
# Process embeddings...
elif job["status"] in ["Failed", "Expired"]:
active_jobs.pop(arn)
if active_jobs:
time.sleep(10)
def read_embeddings_from_s3(s3_uri):
"""Read JSONL embeddings from S3. Returns list of {startTime, endTime, embedding} dicts."""
# Download and parse JSONL from s3_uri (standard S3 GetObject + json.loads per line)
Step 4: Generate metadata tags with Nova Pro or Nova Lite
Generate descriptive tags for videos using Nova Pro (or Nova Lite for better accuracy at lower cost) to enable hybrid search that combines semantic and keyword matching.
VALID_TAGS = [
"person", "vehicle", "animal", "building", "nature", "indoor", "outdoor",
"walking", "running", "sitting", "standing", "talking", "driving",
"day", "night", "sunny", "cloudy", "urban", "rural", "beach", "forest",
"sports", "music", "food", "technology", "crowd", "solo"
]
def generate_tags(video_s3_uri, sample_frame_count=3):
"""Generate descriptive tags using Nova Pro or Nova Lite."""
prompt = f"""Analyze this video and select 10-15 tags from this predefined list that best describe the content:
{', '.join(VALID_TAGS)}
Only return tags from this list as a comma-separated list. Do not invent new tags."""
response = bedrock.converse(
modelId="us.amazon.nova-pro-v1:0", # Or use us.amazon.nova-2-lite-v1:0
messages=[{
"role": "user",
"content": [{
"video": {
"format": "mp4",
"source": {"s3Location": {"uri": video_s3_uri}}
}
}, {
"text": prompt
}]
}]
)
# Parse tags from response and validate against taxonomy
tags_text = response['output']['message']['content'][0]['text']
tags = [tag.strip().lower() for tag in tags_text.split(',')]
# Filter to only valid tags from our taxonomy
valid_tags = [tag for tag in tags if tag in VALID_TAGS]
return valid_tags
Step 5: Index embeddings and tags in OpenSearch Service
Store the generated embeddings and tags in OpenSearch Service using bulk indexing for efficiency.
from opensearchpy import helpers
def index_video_data(video_id, s3_uri, embeddings, tags):
"""Index embeddings and tags in OpenSearch."""
# Prepare bulk actions for k-NN index
knn_actions = []
for idx, emb in enumerate(embeddings):
doc_id = f"{video_id}_{idx}"
knn_actions.append({
"_index": "video-embeddings-knn",
"_id": doc_id,
"_source": {
"video_id": video_id,
"segment_index": idx,
"timestamp": emb['start_time'],
"embedding": emb['embedding'],
"s3_uri": s3_uri
}
})
# Bulk index embeddings
helpers.bulk(opensearch_client, knn_actions)
# Prepare bulk actions for text index
text_actions = []
for idx in range(len(embeddings)):
doc_id = f"{video_id}_{idx}"
text_actions.append({
"_index": "video-embeddings-text",
"_id": doc_id,
"_source": {
"video_id": video_id,
"segment_index": idx,
"tags": " ".join(tags)
}
})
# Bulk index tags
helpers.bulk(opensearch_client, text_actions)
print(f"Indexed {len(embeddings)} segments for video {video_id}")
Step 6: Implement search functionality
After ingestion completes, search the indexed videos three ways. The implementation targets low-latency queries.
Initialize OpenSearch Service client for search
First, create the OpenSearch Service client for search operations:
from opensearchpy import OpenSearch, RequestsHttpConnection
from requests_aws4auth import AWS4Auth
import boto3
def create_opensearch_client():
"""Create OpenSearch client with AWS authentication."""
session = boto3.Session(region_name='us-east-1')
credentials = session.get_credentials()
awsauth = AWS4Auth(
credentials.access_key,
credentials.secret_key,
'us-east-1',
'es',
session_token=credentials.token
)
return OpenSearch(
hosts=[{'host': 'YOUR_OPENSEARCH_ENDPOINT', 'port': 443}],
http_auth=awsauth,
use_ssl=True,
verify_certs=True,
connection_class=RequestsHttpConnection,
timeout=30
)
# Create client
opensearch_client = create_opensearch_client()
Text-to-video semantic search
Convert natural language queries to embeddings using the sync API, then perform a k-NN similarity search:
def search_text_to_video(query_text, opensearch_client, k=10):
"""Search videos using natural language query converted to embedding."""
bedrock_client = boto3.client('bedrock-runtime', region_name='us-east-1')
# Use SINGLE_EMBEDDING task type for text-to-embedding conversion
# VIDEO_RETRIEVAL purpose optimizes embeddings for searching video content
request_body = {
"taskType": "SINGLE_EMBEDDING",
"singleEmbeddingParams": {
"embeddingPurpose": "VIDEO_RETRIEVAL",
"embeddingDimension": 1024,
"text": {
"truncationMode": "END",
"value": query_text
}
}
}
response = bedrock_client.invoke_model(
modelId='amazon.nova-2-multimodal-embeddings-v1:0',
body=json.dumps(request_body),
accept='application/json',
contentType='application/json'
)
response_body = json.loads(response['body'].read())
# Response structure: {"embeddings": [{"embeddingType": "TEXT", "embedding": [...]}]}
query_embedding = response_body['embeddings'][0]['embedding']
# Perform k-NN search against video embeddings
search_body = {
"query": {
"knn": {
"embedding": {
"vector": query_embedding,
"k": k
}
}
},
"size": k,
"_source": ["video_id", "segment_index", "timestamp", "s3_uri"]
}
response = opensearch_client.search(
index="video-embeddings-knn",
body=search_body
)
# Extract results
return [{'score': hit['_score'],
'video_id': hit['_source']['video_id'],
'segment_index': hit['_source']['segment_index'],
'timestamp': hit['_source'].get('timestamp', 0)}
for hit in response['hits']['hits']]
Text search with BM25 (keyword matching)
Use the OpenSearch BM25 scoring for keyword matching on tags without generating embeddings:
def search_text_bm25(search_term, opensearch_client, k=10):
"""Search videos using BM25 keyword matching on tags field."""
# Search text index using match query on tags
search_body = {
"query": {
"match": {
"tags": search_term
}
},
"size": k,
"_source": ["video_id", "segment_index", "tags"]
}
response = opensearch_client.search(
index="video-embeddings-text",
body=search_body
)
return response['hits']['hits'] # Extract results (same pattern as above)
Video-to-video search
Retrieve an existing video’s embedding from OpenSearch Service and search for similar content—no Amazon Bedrock API call needed:
def search_video_to_video(query_video_id, query_segment_index, opensearch_client, k=10):
"""Find similar videos using a reference video segment."""
# Get the embedding from the reference video segment
sample_query = {
"query": {
"bool": {
"must": [
{"term": {"video_id": query_video_id}},
{"term": {"segment_index": query_segment_index}}
]
}
},
"_source": ["video_id", "segment_index", "embedding"]
}
sample_response = opensearch_client.search(
index="video-embeddings-knn",
body=sample_query
)
if not sample_response['hits']['hits']:
return []
sample_doc = sample_response['hits']['hits'][0]['_source']
query_embedding = sample_doc.get('embedding')
# Perform k-NN search with the embedding
search_body = {
"query": {
"knn": {
"embedding": {
"vector": query_embedding,
"k": k
}
}
},
"size": k,
"_source": ["video_id", "segment_index", "timestamp"]
}
response = opensearch_client.search(
index="video-embeddings-knn",
body=search_body
)
return response['hits']['hits'] # Extract results as needed
Hybrid search
Combine semantic k-NN and BM25 keyword matching by retrieving results from both indexes and merging with weighted scoring:
def search_hybrid(query_text, opensearch_client, k=10, vector_weight=0.7, text_weight=0.3):
"""Hybrid search combining k-NN semantic search and BM25 text matching."""
# Generate query embedding (use same code as search_text_to_video above)
query_embedding = generate_query_embedding(query_text) # See text-to-video example
# Get k-NN results (same query as search_text_to_video)
knn_response = opensearch_client.search(
index="video-embeddings-knn",
body={"query": {"knn": {"embedding": {"vector": query_embedding, "k": 20}}}, "size": 20}
)
# Get BM25 text results (same query as search_text_bm25)
text_response = opensearch_client.search(
index="video-embeddings-text",
body={"query": {"match": {"tags": query_text}}, "size": 20}
)
# Combine results with weighted scoring
knn_hits = knn_response['hits']['hits']
text_hits = text_response['hits']['hits']
combined = {}
for hit in knn_hits:
vid = hit['_source']['video_id']
seg = hit['_source']['segment_index']
key = f"{vid}_{seg}"
combined[key] = {
'video_id': vid,
'segment_index': seg,
'tags': hit['_source'].get('tags', ''),
'vector_score': hit['_score'],
'text_score': 0,
'combined_score': hit['_score'] * vector_weight
}
for hit in text_hits:
vid = hit['_source']['video_id']
seg = hit['_source']['segment_index']
key = f"{vid}_{seg}"
if key in combined:
combined[key]['text_score'] = hit['_score']
combined[key]['combined_score'] += hit['_score'] * text_weight
else:
combined[key] = {
'video_id': vid,
'segment_index': seg,
'tags': hit['_source'].get('tags', ''),
'vector_score': 0,
'text_score': hit['_score'],
'combined_score': hit['_score'] * text_weight
}
# Sort by combined score and return top k
sorted_results = sorted(combined.values(), key=lambda x: x['combined_score'], reverse=True)[:k]
return sorted_results
# Usage example - search with natural language query
query = "person walking on beach at sunset"
hybrid_results = search_hybrid(query, opensearch_client, k=10)
for r in hybrid_results:
print(f"Combined: {r['combined_score']:.4f} (Vector: {r['vector_score']:.4f}, Text: {r['text_score']:.4f})")
print(f" Video: {r['video_id']}, Segment: {r['segment_index']}")
print(f" Tags: {r['tags']}\n")
Search performance at scale
After indexing all 792,218 videos, we measured search performance across all three methods.
The measured query latencies at 792,218 videos are as follows:
- Semantic k-NN search: ~76ms (using HNSW logarithmic scaling)
- BM25 text search: ~30ms
- Hybrid search: ~106ms
After indexing and storing all 792,218 videos and generating embeddings, the storage requirements are as follows:
- k-NN index: 28.8 GB for 792K videos
- Text index: 1.0 GB for 792K videos
- Total: 29.8 GB (manageable on modern OpenSearch clusters)
The Hierarchical Navigable Small World (HNSW) algorithm used for k-NN search provides logarithmic time complexity, which means search times grow slowly as the dataset increases. All three search methods maintain sub-200 ms response times even at 792K video scale, meeting production requirements for interactive search applications.
Things to know
Performance and cost considerations
Video processing time depends on video length. In our testing, a 45-second video took approximately 70 seconds to process using the async API. The processing includes automatic segmentation, embedding generation for each segment, and output to Amazon S3. Search operations scale efficiently—our testing shows that even at 792K videos, semantic search completes in under 80 ms, text search in under 30 ms, and hybrid search in under 11 0ms.Use 1024-dimensional embeddings instead of 3072 to reduce storage costs while maintaining accuracy. Nova Multimodal Embeddings charges per second of video input ($0.00056/second batch), so video duration—not embedding dimension or segmentation—determines processing cost. The async API is more cost-effective than processing frames individually. For OpenSearch Service, using r6g instances provides better price-performance than earlier instance types, and you can implement tiering to move cold data to Amazon S3 for additional savings.
Scaling to production
For production deployments with large video libraries, consider using AWS Batch to process videos in parallel across multiple compute instances. You can partition your video dataset and assign subsets to different workers. Monitor OpenSearch Service cluster health and scale data nodes as your index grows. The two-index architecture scales well because k-NN and text searches can be optimized independently.
Search accuracy tuning
Tune hybrid search weights based on your use case. The default 0.7/0.3 split (vector/text) favors semantic similarity for most scenarios. If you have high-quality metadata tags, increasing the text weight to 0.5 can improve results. We recommend that you test different configurations with your specific content to find a balance.
Cleanup
To avoid ongoing charges, delete the resources that you created:
- Delete the OpenSearch Service domain from the Amazon OpenSearch Service console
- Empty and delete the S3 buckets used for videos and embeddings
- Delete any IAM roles created specifically for this solution
Note that Amazon Bedrock charges are based on usage, so no cleanup is needed for the Amazon Bedrock models themselves.
Conclusion
This walkthrough covered building a multimodal video search system for natural language queries across video content. The solution uses Amazon Bedrock Nova models to generate embeddings. These embeddings capture both audio and visual information, stores them efficiently in OpenSearch Service using a two-index architecture, and provides three search modes for different use cases.The async processing approach scales to handle large video libraries, and the hybrid search capability combines semantic and keyword-based matching for maximum accuracy. You can extend this foundation by adding features like video-to-video similarity search, implementing caching for frequently searched queries, or integrating with AWS Batch for parallel processing of large datasets.
To learn more about the technologies used in this solution, see Amazon Nova Multimodal Embeddings and Hybrid Search with Amazon OpenSearch Service.

Fast and maintainable patterns for fetching from a database
In this post, I want to talk about how we can build better application frameworks and how we can structure code in our applications more clearly.
Both of these are just means of working towards our real goal: finding ways to make our application code faster and more maintainable.
When I say “application code”, this time I’m mostly thinking of server-side (web backend) development, where you have a database that you perform many fetches from. Technically speaking, nothing here is database-specific, but the idea of a database is the right mental model here, so it’s the terminology I’ll use.
I’m going to focus on the sort of application frameworks where you fetch individual pieces of stored data (maybe using an ORM library). In particular, this post will tell you little about how to improve code that uses, say, complex SQL queries with joins.
These are techniques that I’ve seen work at scale – in codebases developed by thousands of engineers, containing many millions of lines of code, and used by billions of users.
I’m confident they make sense on small teams too.
Introduction
For the code examples in this post, I’ll give my database functions names like fetchPosts()
. It could have just as easily been something like Post.fetchAll()
or DB.queryAll(Post)
. The exact naming and syntax here isn’t what I’m focused on.
As an example, let’s say the app we’re building has a blog component, and we’d like to render a summary of published posts, with the post title, author, number of times it’s been viewed, and a fun fact about that view count number. The list we’re rendering will look like this:
- “What makes a sofa a sofa?” by Sophie A
View count: 496 (the third perfect number!) - “Salami for cats (as a treat)” by Joseph A
View count: 17 (the number of distinct wallpaper groups) - “Why is the sky blue?” by Sophie A
View count: 0
To fetch the data needed to render this, the most straightforward code we might write here could look something like this:
// [{
// title: 'What makes a sofa a sofa?',
// authorName: 'Sophie A',
// viewCount: 496,
// funFact: 'the third perfect number!',
// }, ...]
async function buildPostsSummary() {
let posts = await fetchPosts();
let summary = [];
for (let post of posts) {
let author = await post.fetchAuthor();
let stats = await post.fetchStats();
let funFact =
stats.viewCount > 0 ? await fetchFunFact(stats.viewCount) : undefined;
summary.push({
title: post.title,
authorName: author.name,
viewCount: stats.viewCount,
funFact,
});
}
return summary;
}
This code is some of the simplest code we can write to solve this task – we fetch the posts, then for each post we fetch the author, the view stats, and the fun fact. I’ve added a conditional where we fetch the fun fact (suppose fetchFunFact
only takes non-zero numbers) to make it a little more representative of most real-world code.
However, this code likely doesn’t run very fast. In particular, we talk to our database three separate times for most posts in the list. Worse, we loop over the posts serially; that is, we process them one by one, waiting for each post’s data to finish before we even look at the next post in the list.
Batching
One major improvement would be to make these requests in batch, where we ask our database to fetch multiple things at once. Imagining we have functions such as fetchManyAuthors(posts)
which takes a list of posts and returns a list of authors corresponding 1:1 with the list of posts, we could rewrite our code to process the whole list of posts at once:
async function buildPostsSummary() {
let posts = await fetchPosts();
let authors = await fetchManyAuthors(posts);
let stats = await fetchManyStats(posts);
// We only want to fetch facts for non-zero view counts.
// It gets more complicated than a simple .filter() because we need
// to track which view count came from which index.
// For example, we need to:
// ...turn [496, 17, 0, 2] into [496, 17, 2],
// ...pass that to fetchManyFunFacts(),
// ...get back three fun facts [factA, factB, factC],
// ...then space it into [factA, factB, undefined, factC] so that
// it matches up with [post0, post1, post2, post3].
let nonZeroViewCounts = [];
let nonZeroViewCountIndices = [];
stats.forEach((stat, idx) => {
if (stat.viewCount > 0) {
nonZeroViewCounts.push(stat.viewCount);
nonZeroViewCountIndices.push(idx);
}
});
let nonZeroFunFacts = await fetchManyFunFacts(nonZeroViewCounts);
let funFacts = Array(posts.length).fill(undefined);
for (let i = 0; i < nonZeroFunFacts.length; i++) {
let originalIndex = nonZeroViewCountIndices[i];
funFacts[originalIndex] = nonZeroFunFacts[i];
}
// Now our variables posts, authors, stats, and funFacts are all the
// same length and have the data we need. We can now stitch them back
// together:
let summary = [];
for (let i = 0; i < posts.length; i++) {
summary.push({
title: posts[i].title,
authorName: authors[i].name,
viewCount: stats[i].viewCount,
funFact: funFacts[i],
});
}
return summary;
}
Whew.
The good news is this now talks to the database only 4 times total.
The bad news is that the code is a small nightmare. The first few lines started out OK – but as soon as you run into anything more complicated, even the one-line conditional we had in our original function, the code turns into a disaster.
Switching from processing one item at a time to processing many at once makes our code dramatically more complex. This is bad news both because it’s annoying to write and because it’s much easier to introduce bugs. (Do you know if my code snippet has a bug in it? Me neither.)
Note that we’re also now coupled to the particular array-of-posts structure we’ve chosen. For example, what if we had multiple separate blogs, and we wanted to fetch this summary for each blog’s respective posts? Unless we restructure this entire function, we’d end up fetching the data for each blog separately, rather than having it fully batched together.
The fact that this is annoying to write also means that this optimized version is less likely to get written in the first place. Devs won’t want to write this, and so they’ll usually gravitate towards simpler alternatives, even if that means having a slower app.
So we need to find another approach.
Parallelism
Let’s think back to our original example. Our biggest problem is that we were processing the posts array completely serially. With a small tweak, we can make it process each post in parallel, by initiating processing for every post then waiting for them all to finish with a Promise.all
.
async function buildPostsSummary() {
let posts = await fetchPosts();
let summary = Promise.all(posts.map((post) => buildPostSummary(post)));
return summary;
}
async function buildPostSummary(post) {
let author = await post.fetchAuthor();
let stats = await post.fetchStats();
let funFact =
stats.viewCount > 0 ? await fetchFunFact(stats.viewCount) : undefined;
return {
title: post.title,
authorName: author.name,
viewCount: stats.viewCount,
funFact,
};
}
This code is pretty manageable. Our extracted helper function only needs to worry about one post, which makes coding easier. We also now use a .map(...)
and don’t need mutation to build up the summary
list now, which feels a little cleaner to me.
What are the performance characteristics of this? It depends on how these fetch*()
functions are implemented.
The most straightforward implementation of these would send a separate request to the database for each of the 3 things we’re fetching per post, plus the one request to fetch the posts in the first place – if we had 100 posts, then we’d talk to our database around 301 times. Many of these requests would happen concurrently, so it will be much faster than what we started with.
However, there’s a typically a sizable fixed cost for each database request we make. Since we’re incurring that cost many times, this is still slower than the optimized, batched (nightmare) solution we wrote above.
Automatic batching
It would be ideal if we could reduce the number of requests while keeping this clean coding style. What we want is to leave the individual calls to fetchAuthor
unchanged (for example) but have that result in a single batched database request behind the scenes. Luckily, this is possible.
The trick is that fetchAuthor
should wait – even for just a fraction of a millisecond – before sending the request to the database. If anyone else calls fetchAuthor
in that moment, we can combine them into a single request containing both fetches. When we map over our posts
array to process them in parallel, all of the fetchAuthor
calls are initiated at approximately the same time, which means they can all be batched together.
Our fetchStats
and fetchFunFact
functions should batch in the same way. Typically, you wouldn’t implement this batching separately for each type of data that can be fetched; if they share an underlying database, you would implement the batching at that layer.
That way, if you want to fetch two different kinds of data at the same time, those can also be batched into a single database request. (Ideally, our database’s underlying batch API would allow streaming responses, so that if some pieces of data are ready before the rest, we can immediately begin work on their next steps.)
Optimal parallelism
At this point, we’re in a pretty decent state. But let’s look at another optimization opportunity. Let’s reread this code from above:
async function buildPostSummary(post) {
let author = await post.fetchAuthor();
let stats = await post.fetchStats();
let funFact =
stats.viewCount > 0
? await fetchFunFact(stats.viewCount)
: undefined;
return ...;
}
Note that we wait until the author has been fetched before we begin fetching the post’s stats. We can parallelize these too. You might try to fix it by parallelizing the author and stats fetches:
async function buildPostSummary(post) {
let [
author,
stats,
] = await Promise.all([
post.fetchAuthor(),
post.fetchStats(),
]);
let funFact =
stats.viewCount > 0
? await fetchFunFact(stats.viewCount)
: undefined;
return ...;
}
This is better but isn’t optimal: if fetching the author takes longer than fetching the stats, we unnecessarily wait for the author before we fetch the fun fact.
There are a few ways we can structure this for optimal parallelism. You only want to fetch the stats once, so maybe you’d try having one “thread” fetch the stats and fun fact, in parallel with the author fetch:
async function buildPostSummary(post) {
let [
author,
[stats, funFact],
] = await Promise.all([
post.fetchAuthor(),
fetchStatsAndFunFact(),
]);
return ...;
async function fetchStatsAndFunFact() {
let stats = await post.fetchStats();
let funFact =
stats.viewCount > 0
? await fetchFunFact(stats.viewCount)
: undefined;
return [stats, funFact];
}
}
This does run with optimal parallellism.
However, take a moment to notice that our code structure is now tied to the specific structure of the data dependencies we’re using.
For example, imagine that a change to our app now means that we do need to fetch the author before fetching the stats. We’d probably end up rewriting back to the 3-serial-fetches structure we had before. What would ideally be a one-line change now means we need to refactor our whole function. In this small example with 3 fetches, it’s doable. In a real-world example that might have 10+ fetches with complicated interdependencies, it’s hard to see what the optimal structure is, and it’s harder to do the refactor too.
How else can we structure this?
Let’s look back at what our function returns (eliding the actual data fetching code, which we’ll soon rewrite):
async function buildPostSummary(post) {
...
return {
title: post.title,
authorName: ...,
viewCount: ...,
funFact: ...,
};
}
We know we need to fetch three pieces of information – the author name, the view count, and the fun fact. Ideally, we’d like to think about these separately and not have to exert human brainpower on understanding the interdependencies between them.
Let’s write code that considers these three independently:
async function buildPostSummary(post) {
async function fetchAuthorName() {
let author = await post.fetchAuthor();
return author.name;
}
async function fetchViewCount() {
let stats = await post.fetchStats();
return stats.viewCount;
}
async function fetchViewCountFunFact() {
let stats = await post.fetchStats();
return;
stats.viewCount > 0 ? await fetchFunFact(stats.viewCount) : undefined;
}
let [authorName, viewCount, funFact] = await Promise.all([
fetchAuthorName(),
fetchViewCount(),
fetchViewCountFunFact(),
]);
return { title: post.title, authorName, viewCount, funFact };
}
Now, we first specify how to fetch the three pieces of info we need; then, we initiate and wait for the trio together. This will runs with the same optimal parallelism structure, but it happens automatically for us; we didn’t need to write it out by hand.
I love this code: it is more lines of code than before, but the code is less “clever” – which is a good thing. (You could also write this in an object-oriented fashion with a class if you prefer.)
I wrote post.fetchStats()
in my fetchViewCountFunFact()
function; it would also work to do let viewCount = fetchViewCount();
if you wanted to reuse some code. These inner functions are pretty simple in this example, but they would often be more complex in the real world.
The only issue with this code is that we may now be fetching the stats twice. In fact, we almost never want to fetch one thing twice in a single web request. To make sure this doesn’t happen, the best solution here (that I know of) is…
Caching (within a request)
Add caching. A lot of it. Here’s how:
I’ll recommend that most caches shouldn’t last longer than the web request. This is for a few reasons: first, because the memory is freed at the end of the request, it’s easier to cache more without worrying about memory usage (it’s rare that a user-facing request will fetch or create more data than fits in available RAM); second, users don’t need to worry about getting a stale result when loading the page; third, scoping to one user’s request reduces the chance of accidental privacy leaks due to “cross-contamination” between different users’ data.
But with that in mind, we can get a huge win by caching essentially all reads from our database. Just like the auto-batching, this is typically best implemented at a lower level of your application frameworks so that all of your app code that fetches from your database can benefit.
Even in an application built by people trying to be judicious about data fetching and make sure each piece of data is fetched once and at the right time (a cumbersome task, as we saw above), people make mistakes and it’s likely you would see wins from implementing this. But the bigger advantage here is that it allows us to write clearer, more maintainable code.
We can also add caching in higher levels of our application. Whenever there’s a complex computation you wouldn’t want to redo, just cache it – again, for the length of the request.
For example, we might put a @memoize
decorator on the Post object’s .fetchStats()
function, which will make a cache that lives only as long as that Post is in memory. Or on the fetchViewCount()
function we just wrote – so that it only runs once even if we change fetchViewCountFunFact()
to use it.
With the small tweak of adding memoization, the last code snippet above – and code like it – is efficient, easy to write, and maintainable.
Conclusion
This is an outline of how to build infrastructure that allows application code to be simple while still being fast and clean.
All of the techniques I’ve mentioned are ultimately motivated by one thing:
Facilitating local reasoning.
What I mean by that is: you should be able to worry about each part of your code in isolation, without holding the entire system in your head. In my experience, this is the key to making complex systems scale, especially (but not only) in a large organization.
For example, you should be able to edit the three helper functions fetchAuthorName
, fetchViewCount
, and fetchViewCountFunFact
independently without worrying about affecting the others. When you call a function (like buildPostSummary
itself), you ideally shouldn’t need to worry about whether what it fetches overlaps with other functions you’re calling.
Some of these techniques are built into dataloader, an open-source project that is based directly on the same systems I gleaned these techniques from.
But it’s more about the principles – when you understand them, it’s not hard to write your own implementation.

In September, 2025, we introduced the Data Commons Model Context Protocol (MCP) server to provide a standard way for AI agents to interact with Data Commons data natively. This was followed by the Gemini CLI extension, which streamlined the setup process for Gemini CLI users.
While these tools successfully opened the door for natural language data exploration, they relied on local Python environments, which created some challenges. Installing and running open-source tools was not compatible with high-security environments; and hosting a local MCP server lacked the scalability needed for developers who want to publish their own query agents.
Today, we’re taking the next step to make it easier for everyone to use datacommons.org with an LLM by launching the hosted Data Commons MCP service in Google Cloud Platform. Now you can just connect to the free service and let Google manage the rest – no need to worry about Python environments, resource management, version releases, security compliance etc.
The MCP server provides a standardized way for AI agents to consume Data Commons data natively. Analysts can create insights by asking high-level questions in natural language with the MCP returning data from trusted sources, while developers can easily create AI agents customized for their needs. For example, you can get statistical answers to questions like "What is the correlation between unemployment levels and obesity rates in U.S. states?" or "Rank-order the GDP of every eastern European country".
If you're already using the Data Commons Gemini CLI extension, you don't need to do anything. The next time you run Gemini CLI, the extension will automatically update itself to connect to the server over the web instead of starting up a local server instance. If you haven't used the extension before, see Use the Gemini CLI extension to get started.
If you're using Gemini CLI without the extension, or any other agent, you'll need to get a free Data Commons API key and update your configuration to point to the hosted server. For complete details, see Use Gemini CLI.
"mcpServers": {
"datacommons-mcp": {
"httpUrl": "https://api.datacommons.org/mcp",
"headers": {
"X-API-Key": "YOUR DC API KEY"
}
}
}
And as always, if you’re interested in sharing your cool usage of Data Commons or have feedback, please email us at support@datacommons.org.
Note: The hosted MCP server can only be used to query datacommons.org. If you're running your own Custom Data Commons instance, you'll still need to run your own MCP server. See Run MCP tools for more information.

Everything you never wanted to know about visually-hidden
Nobody asked for it but nevertheless, I present to you my definitive “it depends” tome on visually-hidden web content. I’ll probably make an amendment before you’ve finished reading. If you enjoy more questions than answers, buckle up! I’ll start with the original premise, even though I stray off-topic on tangents and never recover.
The question
I was
Is there still any point to most styles in visually hidden classes in ’26?
Any point to shrinking dimensions to
1px
and settingoverflow: hidden
whenclip-path
to nothing viainset(50%)
/circle(0)
reduces clickable area to nothing? And then no1px
dimensions = no need forwhite-space
.
Ana proposed the following:
.visually-hidden { /* shouldn't this be enough in 2026? */
position: absolute; /* take out of document flow */
clip-path: circle(0); /* reduce clickable area to nothing */
}
Is this enough in 2026?
As an occasional purveyor of the visually-hidden
class myself, the question wriggled its way into my brain. I felt compelled to investigate the whole ordeal. Spoiler: I do not have a satisfactory yes-or-no answer, but I do have a wall of text!
Table of contents
I went so deep down the rabbit hole I must start with a table of contents:
- Accessibility notice
- Class walkthrough
- Where it all began
- Further adaptations
- Minimum viable technique
- Native visually-hidden
Accessibility notice
I’m writing this based on the assumption that a visually-hidden
class is considered acceptable for specific use cases. My final section on native visually-hidden addresses the bigger accessibility concerns. It’s not easy to say where this technique is appropriate. It is generally agreed to be OK but a symptom of — and not a fix for — other design issues.
Appropriate use cases for visually-hidden
are far fewer than you think.
Class walkthrough
Skip to the history lesson if you’re familiar.
visually-hidden
, sr-only
— there have been many variations on the class name. I’ve looked at popular implementations and compiled the kitchen sink version below.
.visually-hidden {
border: 0;
clip: rect(0 0 0 0);
clip-path: inset(50%);
height: 1px;
margin: -1px;
overflow: hidden;
padding: 0;
position: absolute;
white-space: nowrap;
width: 1px;
}
Please don’t copy this as a golden sample. It merely encompasses all I’ve seen.
There are variations on the selector using pseudo-classes that allow for focus. Think “skip to main content” links, for example.
What is the purpose of the visually-hidden
class? The idea is to hide an element visually, but allow it to be discovered by assistive technology. Screen readers being the primary example. The element must be removed from layout flow. It should leave no render artefacts and have no side effects. It does this whilst trying to avoid the bugs and quirks of web browsers.
If this sounds and looks just a bit hacky to you, you have a high tolerance for hacks! It’s a massive hack! How was this normalised? We’ll find out later.
I’ll whittle down the visually-hidden
properties for those unfamiliar.
.visually-hidden {
position: absolute;
}
Absolute positioning is vital to remove the element from layout flow. Otherwise the position of surrounding elements will be affected by its presence.
.visually-hidden {
clip: rect(0 0 0 0);
clip-path: inset(50%);
}
This crops the visible area to nothing. clip
remains as a fallback but has long been deprecated and is obsolete. All modern browsers support clip-path
.
.visually-hidden {
border: 0;
padding: 0;
}
These two properties remove styles that may add layout dimensions.
.visually-hidden {
height: 1px;
margin: -1px;
width: 1px;
}
This group effectively gives the element zero dimensions. There are reasons for 1px
instead of 0px
and negative margin that I’ll cover later.
.visually-hidden {
overflow: hidden;
}
Another property to ensure no visible pixels are drawn. I’ve seen the newer clip
value used but what difference that makes if any is unclear.
.visually-hidden {
white-space: nowrap;
}
This was added to address text wrapping inside the 1px
square (I’ll explain later).
So basically we have position: absolute
and a load of properties that attempted to make the element invisible. We cannot use display: none
or visibility: hidden
or content-visibility: hidden
because those remove elements from the accessibility tree.
So the big question remains: why must we still ‘zero’ the dimensions? Why is clip-path
not sufficient? To make sense of this mystery I went back to the beginning.
Where it all began
It was tricky to research this topic because older articles have been corrected with modern information. I recovered many details from the archives and mailing lists with the help of those involved. They’re cited along the way.
Our journey begins November 2004.
A draft document titled “CSS Techniques for WCAG 2.0” edited by Wendy Chisholm and Becky Gibson includes a technique for invisible labels.
While it is usually best to include visual labels for all form controls, there are situations where a visual label is not needed due to the surrounding textual description of the control and/or the content the control contains. Users of screen readers, however, need each form control to be explicitly labeled so the intent of the control is well understood when navigated to directly.
The following CSS was provided:
.nosize {
position: absolute;
width: 0px;
height: 0px;
overflow: hidden;
}
Could this be the original visually-hidden
class?
My research jumped through decades but eventually I found an email thread “CSS and invisible labels for forms” on the W3C WAI mailing list. This was a month prior, preluding the WCAG draft. A different technique from Bob Easton was noted:
.off-left {
position: absolute;
left: -999px;
width: 990px;
}
The beauty of this technique is that it enables using as much text as we feel appropriate, and the elements we feel appropriate. Imagine placing instructive text about the accessibility features of the page off left (as well as on the site’s accessibility statement). Imagine interspersing “start of…” landmarks through a page with heading tags. Or, imagine parking full lists off left, lists of access keys, for example. Screen readers can easily collect all headings and read complete lists. Now, we have a made for screen reader technique that really works!
Screenreader Visibility - Bob Easton (2003)
Easton attributed both Choan Gálvez and Dave Shea for their contributions.
In same the thread, Gez Lemon proposed overflow
to ensure that text doesn’t bleed into the display area
. Following up, Becky Gibson shared a test case covering the ideas.
.offscreen {
position: absolute;
width: 0px;
overflow:hidden;
}
.offscreen2 {
position: absolute;
left: -200em;
}
Lemon later published an article “Invisible Form Prompts” about the WCAG plans which attracted plenty of commenters including Bob Easton.
The resulting WCAG draft guideline discussed both the nosize
and offscreen
ideas.
Note that instead of using the nosize style described above, you could instead use postion:absolute; and left:-200px; to position the label “offscreen”. This technique works with the screen readers as well. Only position elements offscreen in the top or left direction, if you put an item off to the right or the bottom, many browsers will add scroll bars to allow the user to reach the content.
Two options were known and considered towards the end of 2004.
- Zero dimensions
- Position off-screen
Why not both? Indeed, it appears Paul Bohman on the WebAIM mailing list suggested such a combination in February 2004.
.hidden {
position: absolute;
left: 0px
top: -100px;
width: 1px;
height: 1px;
overflow: hidden;
}
Bohman even discovered possibly the first zero width bug.
I originally recommended setting the height and width to 0 pixels. This works with JAWS and Home Page Reader. However, this does not work with Window Eyes. If you set the height and width to 1 pixel, then the technique works with all browsers and all three of the screen readers I tested.
Re: Hiding text using CSS - Paul Bohman
Later in May 2004, Bohman along with Shane Anderson published a paper on this technique. Citations within included Bob Easton and Tom Gilder.
Aside note: other zero width bugs have been discovered since. Manuel Matuzović noted in 2023 that links in Safari were not focusable.
The zero width story continues as recently as February 2026 (last week).
In browse mode in web browsers, NVDA no longer treats controls with 0 width or height as invisible. This may make it possible to access previously inaccessible “screen reader only” content on some websites.
NVDA 2026.1 Beta TWO now available - NV Access News
Digger further into WebAIM’s email archive uncovered a 2003 thread in which Tom Gilder shared a class for skip navigation links.
a.skip {
position: absolute;
overflow: hidden;
width: 0;
height: 0;
}
I found Gilder’s blog in the web archives introducing this technique.
I thought I’d put down my “skip navigation” link method down in proper writing as people seem to like it (and it gives me something to write about!). Try moving through the links on this page using the keyboard - the first link should magically appear from thin air and allow you to quickly jump to the blog tools, which modern/visual/graphical/CSS-enabled browsers (someone really needs to come up with an acronym for that) should display to the left of the content.
Skip-a-dee-doo-dah - Tom Gilder
Gilder’s post links to a Dave Shea post which in turn mentions the 2002 book “Building Accessible Websites” by Joe Clark. Chapter eight discusses the necessity of a “skip navigation” link due to table-based layout but advises:
Keep them visible!
Well-intentioned developers who already use page anchors to skip navigation will go to the trouble to set the anchor text in the tiniest possible font in the same colour as the background, rendering it invisible to graphical browsers (unless you happen to pass the mouse over it and notice the cursor shape change).
Building Accessible Websites - 08. Navigation - Joe Clark
Clark expressed frustration over common tricks like the invisible pixel.
<a href="#skip">
<img src="/media/core/1x1clear.gif"
alt="[skip navigation links]"
width="1"
height="1"
/>
</a>
It’s clear no visually-hidden
class existed when this was written.
Choan Gálvez informed me that Eric Meyer would have the css-discuss mailing list. Eric kindly searched the backups but didn’t find any earlier discussion. However, Eric did find a thread on the W3C mailing list from 1999 in which Ian Jacobs (IBM) discusses the accessibility of “skip navigation” links.
The desire to visually hide “skip navigation” links was likely the main precursor to the early visually-hidden
techniques. In fact, Bob Easton said as much:
As we move from tag soup to CSS governed design, we throw out the layout tables and we throw out the spacer images. Great! It feels wonderful to do that kind of house cleaning. So, what do we do with those “skip navigation” links that used to be attached to the invisible spacer images?
Screenreader Visibility - Bob Easton (2003)
I had originally missed that in my excitement seeing the off-left
class.
I reckon we’ve reached the source of the visually-hidden
class. At least conceptually. Technically, the class emerged from several ideas, rather than a “eureka” moment. Perhaps more can be gleaned from other CSS techniques such a the desire to improve accessibility of CSS image replacement.
Bob Easton retired in 2008 after a 40 year career at IBM. I reached out to Bob who was surprised to learn this technique was still a topic today†. Bob emphasised the fact that it was always a clumsy workaround
and something CSS probably wasn’t intended to accommodate
. I’ll share more of Bob’s thoughts later.
† I might have overdone the enthusiasm
Let’s take an intermission!
My contact page is where you can send corrections by the way :)
Further adaptations
The visually-hidden
class stabilised for a period. Visit 2006 in the Wayback Machine to see WebAIM’s guide to invisible content — Paul Bohman’s version is still recommended.
Moving forward to 2011, I found Jonathan Snook discussing the “clip method”. Snook leads us to Drupal developer Jeff Burnz the previous year.
[…] we still have the big problem of the page “jump” issue if this is applied to a focusable element, such as a link, like skip navigation links. WebAim and a few others endorse using the LEFT property instead of TOP, but this no go for Drupal because of major pain-in-the-butt issues with RTL.
In early May 2010 I was getting pretty frustrated with this issue so I pulled out a big HTML reference and started scanning through it for any, and I mean ANY property I might have overlooked that could possible be used to solve this thorny issue. It was then I recalled using clip on a recent project so I looked up its values and yes, it can have 0 as a value.
Using CSS clip as an Accessible Method of Hiding Content - Jeff Burnz
It would seem Burnz discovered the clip
technique independently and was probably the first to write about it. Burnz also notes a right-to-left (RTL) issue. This could explain why pushing content off-screen fell out of fashion.
2010 also saw the arrival of HTML5 Boilerplate along with issue #194 in which Jonathan Neal plays a key role in the discussion and comments:
If we want to correct for every seemingly-reasonable possibility of overflow in every browser then we may want to consider [code below]
.visuallyHidden {
border: 0;
clip: rect(0 0 0 0);
height: 1px;
margin: -1px;
overflow: hidden;
padding: 0;
position: absolute;
width: 1px;
}
This was their final decision. I’ve removed !important
for clarity. This is very close to what we have now, no surprise since HTML5 Boilterplate was extremely popular. I’m leaning to conclude that the additional properties are really just there for the “possibility” of pixels escaping containment as much as fixing any identified problem.
Thierry Koblentz covered the state of affairs in 2012 noting that: Webkit, Opera and to some extent IE do not play ball with [clip]
. Koblentz prophesies:
I wrote the declarations in the previous rule in a particular order because if one day clip works as everyone would expect, then we could drop all declarations after clip, and go back to the original
Clip your hidden content for better accessibility - Thierry Koblentz
Sound familiar? With those browsers obsolete, and if clip-path
behaves itself, can the other properties be removed? Well we have 14 years of new bugs features to consider first.
In 2016, J. Renée Beach published: Beware smushed off-screen accessible text. This appears to be the origin of nowrap
(as demonstrated by Vispero.)
Over a few sessions, Matt mentioned that the string of text “Show more reactions” was being smushed together and read as “Showmorereactions”.
Beach’s class did not include the kitchen sink.
.accessible_elem {
clip: rect(1px, 1px, 1px, 1px);
height: 1px;
overflow: hidden;
position: absolute;
white-space: nowrap;
width: 1px;
}
The addition of nowrap
became standard alongside everything else.
Aside note: the origin of margin: -1px
remains elusive. One Bootstrap issue shows it was rediscovered in 2018 to fix a browser bug. However, another HTML5 Boilterplate issue dated 2017 suggests negative margin broke reading order. Josh Comeau shared a <VisuallyHidden>
React component in 2024 without margin. One of many examples showing that it has come in and out of fashion.
We started with WCAG so let’s end there. The latest WCAG technique for “Using CSS to hide a portion of the link text” provides the following code.
.visually-hidden {
clip-path: inset(100%);
clip: rect(1px, 1px, 1px, 1px);
height: 1px;
overflow: hidden;
position: absolute;
white-space: nowrap;
width: 1px;
}
Circa 2020 the clip-path
property was added as browser support increased and clip
became deprecated. An obvious change I’m not sure warrants investigation (although someone had to be first!) That brings us back to what we have today.
Are you still with me?
Minimum viable technique
As we’ve seen, many of the properties were thrown in for good measure. They exist to ensure absolutely no pixels are painted. They were adapted over the years to avoid various bugs, quirks, and edge cases. How many such decisions are now irrelevant?
This is a classic Chesterton’s Fence scenario.
Do not remove a fence until you know why it was put up in the first place.
Well we kinda know why but the specifics are practically folklore at this point. Despite all that research, can we say for sure if any “why” is still relevant?
Back to Ana Tudor’s suggestion.
.visually-hidden {
position: absolute;
clip-path: circle(0);
}
How do we know for sure? The only way is extensive testing. Unfortunately, I have neither the time nor skill to perform that adequately here. There is at least one concern with the code above, Curtis Wilcox noted that in Safari the focus ring behaves differently.
Other minimum viable ideas have been presented before.
Scott O’Hara proposed a different two-liner using transform
.
.vs-hidden {
position: absolute;
transform: scale(0);
}
JAWS, Narrator, NVDA with Edge all seem to behave just fine. As do Firefox with JAWS and NVDA, and Safari on macOS with VoiceOver. Seems also fine with iOS VO+Safari and Android TalkBack with Firefox or Chrome.
In none of these cases do we get the odd focus rings that have occurred with other visually hidden styles, as the content is scaled down to zero. Also because not hacked into a 1px by 1px box, there’s no text wrapping occurring, so no need to fix that issue.
transform scale(0) to visually hide content - Scott O’Hara
Sounds promising!
It turns out Katrin Kampfrath had explored both minimum viable classes a couple of years ago, testing them against the traditional visually-hidden
class.
I am missing the experience and moreover actual user feedback, however, i prefer the screen reader read cursor to stay roughly in the document flow. There are screen reader users who can see. I suppose, a jumping read cursor is a bit like a shifting layout.
Exploring the visually-hidden css - Katrin Kampfrath
Kampfrath’s limited testing found the read cursor size differs for each class. The clip-path
technique was favoured but caution is given.
A few more years ago, Kitty Giraudel tested several ideas concluding that sr-only
was still the most accessible for specific text use.
This technique should only be used to mask text. In other words, there shouldn’t be any focusable element inside the hidden element. This could lead to annoying behaviours, like scrolling to an invisible element.
Hiding content responsibly - Kitty Giraudel
Zell Liew proposed a different idea in 2019.
.hide-accessibly {
position: absolute !important;
opacity: 0;
pointer-events: none;
}
Many developers voiced their opinions, concerns, and experiments over at Twitter. I wanted to share with you what I consolidated and learned.
A new (and easy) way to hide content accessibly - Zell Liew
Liew’s idea was unfortunately torn asunder. Although there are cases like inclusively hiding checkboxes where near-zero opacity is more accessible.
I’ve started to go back in time again!
I’m also starting to question whether this class is a good idea. Unless we are capable and prepared to thoroughly test across every combination of browser and assistive technology — and keep that information updated — it’s impossible to recommend anything.
This is impossible for developers! Why can’t browser vendors solve this natively?
Native visually-hidden
Once you’ve written 3000 words on a twenty year old CSS hack you start to question why it hasn’t been baked into web standards by now.
Ben Myers wrote “The Web Needs a Native .visually-hidden” proposing ideas from HTML attributes to CSS properties. Scott O’Hara responded noting larger accessibility issues that are not so easily handled. O’Hara concludes:
Introducing a native mechanism to save developers the trouble of having to use a wildly available CSS ruleset doesn’t solve any of those underlying issues. It just further pushes them under the rug.
Visually hidden content is a hack that needs to be resolved, not enshrined - Scott O’Hara
Sara Soueidan had floated the topic to the CSS working group back in 2016. Soueidan closed the issue in 2025, coming to a similar conclusion.
I’ve been teaching accessibility for a little less than a decade now and if there’s one thing I learned is that developers will resort to using
visually-hidden
utility to do things that are more often than not just bad design decisions.Yes, there are valid and important use cases. But I agree with all of @scottaohara’s points, and most importantly I agree that we need to fix the underlying issues instead of standardizing a technique that is guaranteed to be overused and misused even more once it gets easier to use.
csswg-drafts comment - Sara Soueidan
Adrian Roselli has a blog post listing priorities for assigning an accessible name to a control. Like O’Hara and Soueidan, Roselli recognises there is no silver bullet.
Hidden text is also used too casually to provide information for just screen reader users, creating overly-verbose content. For sighted screen reader users, it can be a frustrating experience to not be able to find what the screen reader is speaking, potentially causing the user to get lost on the page while visually hunting for it.
My Priority of Methods for Labeling a Control - Adrian Roselli
In short, many believe that a native visually-hidden would do more harm than good. The use-cases are far more nuanced and context sensitive than developers realise. It’s often a half-fix for a problem that can be avoided with better design.
I’m torn on whether I agree that it’s ultimately a bad idea. A native version would give software an opportunity to understand the developer’s intent and define how “visually hidden” works in practice. It would be a pragmatic addition.
The visually-hidden
technique has persisted for over two decades and is still mentioned by WCAG. Yet it remains hacks upon hacks! How has it survived for so long? Is that a failure of developers, or a failure of the web platform?
The web is overrun with inaccessible energy money dedicated to accessibility. Not all problems can be solved with money. But what of the thousands of unpaid hours, whether volunteered or solicited, from those seeking to improve the web? I risk spiralling into a rant about browser vendors’ financial incentives, so let’s wrap up!
I’ll end by quoting Bob Easton from our email conversation:
From my early days in web development, I came to the belief that semantic HTML, combined with faultless keyboard navigation were the essentials for blind users. Experience with screen reader users bears that out. Where they might occasionally get tripped up is due to developers who are more interested in appearance than good structural practices.
The use cases for hidden content are very few, such as hidden information about where a search field is, when an appearance-centric developer decided to present a search field with no visual label, just a cute unlabeled image of a magnifying glass.
[…] The people promoting hidden information are either deficient in using good structural practices, or not experienced with tools used by people they want to help.
Bob ended with:
You can’t go wrong with well crafted, semantically accurate structure.
Ain’t that the truth.

Building Dynamic Forms In React And Next.js
This article has been kindly supported by our dear friends at SurveyJS, JavaScript UI libraries for custom web forms. Keep full ownership of your data. Build JSON-driven forms in your app (React/Angular/Vue) without SaaS limitations. Thank you!
There’s a mental model most React developers share without ever discussing it out loud. That forms are always supposed to be components. This means a stack like:
- React Hook Form for local state (minimal re-renders, ergonomic field registration, imperative interaction).
- Zod for validation (input correctness, boundary validation, type-safe parsing).
- React Query for backend: submission, retries, caching, server sync, and so on.
And for the vast majority of forms — your login screens, your settings pages, your CRUD modals — this works really well. Each piece does its job, they compose cleanly, and you can move on to the parts of your application that actually differentiate your product.
But every once in a while, a form starts accumulating things like visibility rules that depend on earlier answers, or derived values that cascade through three fields. Maybe even entire pages that should be skipped or shown based on a running total.
You handle the first conditional with a useWatch
and an inline branch, which is fine. Then another. Then you’re reaching for superRefine
to encode cross-field rules that your Zod schema can’t express in the normal way. Then, step navigation starts leaking business logic. At some point, you look at what you’ve built and realize that the form isn’t really UI anymore. It’s more of a decision process, and the component tree is just where you happened to store it.
This is where I think the mental model for forms in React breaks down, and it’s really nobody’s fault. The RHF + Zod stack is excellent at what it was designed for. The issue is that we tend to keep using it past the point where its abstractions match the problem because the alternative requires a different way of thinking about forms entirely.
This article is about that alternative. To show this, we’ll build the exact same multi-step form twice:
- With React Hook Form + Zod wired to React Query for submission,
- With SurveyJS, which treats a form as data — a simple JSON schema — rather than a component tree.
Same requirements, same conditional logic, same API call at the end. Then we’ll map exactly what moved and what stayed, and lay out a practical way to decide which model you should use, and when.
The form we’re building:
This form will use a 4-step flow:
Step 1: Details
- First name (required),
- Email (required, valid format).
Step 2: Order
- Unit price,
- Quantity,
- Tax rate,
- Derived:
- Subtotal,
- Tax,
- Total.
Step 3: Account & Feedback
- Do you have an account? (Yes/No)
- If Yes → username + password, both required.
- If No → email already collected in step 1.
- Satisfaction rating (1–5)
- If ≥ 4 → ask “What did you like?”
- If ≤ 2 → ask “What can we improve?”
Step 4: Review
- Only appears if
total >= 100
- Final submission.
This is not extreme. But it’s enough to expose architectural differences.
Part 1: Component-Driven (React Hook Form + Zod)
Installation
npm install react-hook-form zod @hookform/resolvers @tanstack/react-query
Zod Schema
Let’s start with the Zod schema, because that’s usually where the shape of the form gets established. For the first two steps — personal details and order inputs — everything is straightforward: required strings, numbers with minimums, and an enum. The interesting part starts when you try to express the conditional rules.
import { z } from "zod";
export const formSchema = z.object({
firstName: z.string().min(1, "Required"),
email: z.string().email("Invalid email"),
price: z.number().min(0),
quantity: z.number().min(1),
taxRate: z.number(),
hasAccount: z.enum(["Yes", "No"]),
username: z.string().optional(),
password: z.string().optional(),
satisfaction: z.number().min(1).max(5),
positiveFeedback: z.string().optional(),
improvementFeedback: z.string().optional(),
}).superRefine((data, ctx) => {
if (data.hasAccount === "Yes") {
if (!data.username) {
ctx.addIssue({ code: "custom", path: ["username"], message: "Required" });
}
if (!data.password || data.password.length < 6) {
ctx.addIssue({ code: "custom", path: ["password"], message: "Min 6 characters" });
}
}
if (data.satisfaction >= 4 && !data.positiveFeedback) {
ctx.addIssue({ code: "custom", path: ["positiveFeedback"], message: "Please share what you liked" });
}
if (data.satisfaction <= 2 && !data.improvementFeedback) {
ctx.addIssue({ code: "custom", path: ["improvementFeedback"], message: "Please tell us what to improve" });
}
});
export type FormData = z.infer<typeof formSchema>;
Notice that username
and password
are typed as optional()
even though they’re conditionally required because Zod’s type-level schema describes the shape of the object, not the rules governing when fields matter.
The conditional requirement has to live inside superRefine
, which runs after the shape is validated and has access to the full object. That separation is not a flaw; it’s just what the tool is designed for: superRefine
is where cross-field logic goes when it can’t be expressed in the schema structure itself.
What’s also notable here is what this schema doesn’t express. It has no concept of pages, no concept of which fields are visible at which point, and no concept of navigation. All of that will live somewhere else.
Form Component
import { useForm, useWatch } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation } from "@tanstack/react-query";
import { useState, useMemo } from "react";
import { formSchema, type FormData } from "./schema";
const STEPS = ["details", "order", "account", "review"];
type OrderPayload = FormData & { subtotal: number; tax: number; total: number };
export function RHFMultiStepForm() {
const [step, setStep] = useState(0);
const mutation = useMutation({
mutationFn: async (payload: OrderPayload) => {
const res = await fetch("/api/orders", {
method: "POST",
headers: { "Content-Type": "application/json" },
body: JSON.stringify(payload),
});
if (!res.ok) throw new Error("Failed to submit");
return res.json();
},
});
const {
register,
control,
handleSubmit,
formState: { errors },
} = useForm<FormData>({
resolver: zodResolver(formSchema),
defaultValues: {
price: 0,
quantity: 1,
taxRate: 0.1,
satisfaction: 3,
hasAccount: "No",
},
});
const price = useWatch({ control, name: "price" });
const quantity = useWatch({ control, name: "quantity" });
const taxRate = useWatch({ control, name: "taxRate" });
const hasAccount = useWatch({ control, name: "hasAccount" });
const satisfaction = useWatch({ control, name: "satisfaction" });
const subtotal = useMemo(() => (price ?? 0) * (quantity ?? 1), [price, quantity]);
const tax = useMemo(() => subtotal * (taxRate ?? 0), [subtotal, taxRate]);
const total = useMemo(() => subtotal + tax, [subtotal, tax]);
const onSubmit = (data: FormData) => mutation.mutate({ ...data, subtotal, tax, total });
const showSubmit = (step === 2 && total < 100) || (step === 3 && total >= 100)
return (
<form onSubmit={handleSubmit(onSubmit)}>
{step === 0 && (
<>
<input {...register("firstName")} placeholder="First Name" />
<input {...register("email")} placeholder="Email" />
</>
)}
{step === 1 && (
<>
<input type="number" {...register("price", { valueAsNumber: true })} />
<input type="number" {...register("quantity", { valueAsNumber: true })} />
<select {...register("taxRate", { valueAsNumber: true })}>
<option value="0.05">5%</option>
<option value="0.1">10%</option>
<option value="0.15">15%</option>
</select>
<div>Subtotal: {subtotal}</div>
<div>Tax: {tax}</div>
<div>Total: {total}</div>
</>
)}
{step === 2 && (
<>
<select {...register("hasAccount")}>
<option value="Yes">Yes</option>
<option value="No">No</option>
</select>
{hasAccount === "Yes" && (
<>
<input {...register("username")} placeholder="Username" />
<input {...register("password")} placeholder="Password" />
</>
)}
<input type="number" {...register("satisfaction", { valueAsNumber: true })} />
{satisfaction >= 4 && (
<textarea {...register("positiveFeedback")} />
)}
{satisfaction <= 2 && (
<textarea {...register("improvementFeedback")} />
)}
</>
)}
{step === 3 && total >= 100 && <div>Review and submit</div>}
<div>
{step > 0 && <button type="button" onClick={() => setStep(step - 1)}>Back</button>}
{showSubmit ? (
<button type="submit" disabled={mutation.isPending}>
{mutation.isPending ? "Submitting…" : "Submit"}
</button>
) : step < STEPS.length - 1 ? (
<button type="button" onClick={() => setStep(step + 1)}>Next</button>
) : null}
</div>
{mutation.isError && <div>Error: {mutation.error.message}</div>}
</form>
);
}
There’s quite a lot happening here, and it’s worth slowing down to notice where things ended up.
- The derived values —
subtotal
,tax
,total
— are computed in the component viauseWatch
anduseMemo
because they depend on live field values and there’s no other natural place for them. - The visibility rules for
username
,password
,positiveFeedback
, andimprovementFeedback
live in JSX as inline conditionals. - The step-skipping logic — the review page only appearing when
total >= 100
— is embedded into theshowSubmit
variable and the render condition on step 3. - Navigation itself is just a
useState
counter that we’re manually incrementing. - React Query handles retries, caching, and invalidation. The form just calls
mutation.mutate
with validated data.
None of this is wrong, per se. This is still idiomatic React, and the component is quite performant thanks to how RHF isolates re-renders.
But if you were to hand this to someone who hadn’t written it and ask them to explain under what conditions the review page appears, they’d have to trace through showSubmit
, the step 3 render condition, and the nav button logic — three separate places — to reconstruct a rule that could have been stated in one line.
The form works, yes, but the behavior isn’t really inspectable as a system. It has to be executed mentally.
More importantly, changing it requires engineering involvement. Even a small tweak, like adjusting when the review step shows up, means editing the component, updating validation, opening a pull request, waiting for review, and deploying again.
Part 2: Schema-Driven (SurveyJS)
Now let’s build the same flow using a schema.
Installation
npm install survey-core survey-react-ui @tanstack/react-query
survey-core
The MIT-licensed platform-independent runtime engine that powers SurveyJS’s form rendering — the part we care about here. It takes a JSON schema, builds an internal model from it, and handles everything that would otherwise live in your React component: evaluating visibility expressions, computing derived values, managing page state, tracking validation, and deciding what “complete” means given which pages were actually shown.survey-react-ui
The UI / rendering layer that connects that model to React. It’s essentially a<Survey model={model} />
component that re-renders whenever the engine’s state changes. SurveyJS UI libraries are also available for Angular, Vue3, and many other frameworks.
Together, they give you a fully functional, multi-page form runtime without writing a single line of control flow.
The schema format itself is, as said before, just a JSON — no DSL or anything proprietary. You can inline it, import it from a file, fetch it from an API, or store it in a database column and hydrate it at runtime.
The Same Form, As Data
Here’s the same form, this time expressed as a JSON object. The schema defines everything: structure, validation, visibility rules, derived calculations, page navigation — and hands it to a Model
that evaluates it at runtime. Here’s what that looks like in full:
export const surveySchema = {
title: "Order Flow",
showProgressBar: "top",
pages: [
{
name: "details",
elements: [
{ type: "text", name: "firstName", isRequired: true },
{ type: "text", name: "email", inputType: "email", isRequired: true, validators: [{ type: "email", text: "Invalid email" }] }
]
},
{
name: "order",
elements: [
{ type: "text", name: "price", inputType: "number", defaultValue: 0 },
{ type: "text", name: "quantity", inputType: "number", defaultValue: 1 },
{
type: "dropdown",
name: "taxRate",
defaultValue: 0.1,
choices: [
{ value: 0.05, text: "5%" },
{ value: 0.1, text: "10%" },
{ value: 0.15, text: "15%" }
]
},
{
type: "expression",
name: "subtotal",
expression: "{price} * {quantity}"
},
{
type: "expression",
name: "tax",
expression: "{subtotal} * {taxRate}"
},
{
type: "expression",
name: "total",
expression: "{subtotal} + {tax}"
}
]
},
{
name: "account",
elements: [
{
type: "radiogroup",
name: "hasAccount",
choices: ["Yes", "No"]
},
{
type: "text",
name: "username",
visibleIf: "{hasAccount} = 'Yes'",
isRequired: true
},
{
type: "text",
name: "password",
inputType: "password",
visibleIf: "{hasAccount} = 'Yes'",
isRequired: true,
validators: [{ type: "text", minLength: 6, text: "Min 6 characters" }]
},
{
type: "rating",
name: "satisfaction",
rateMin: 1,
rateMax: 5
},
{
type: "comment",
name: "positiveFeedback",
visibleIf: "{satisfaction} >= 4"
},
{
type: "comment",
name: "improvementFeedback",
visibleIf: "{satisfaction} <= 2"
}
]
},
{
name: "review",
visibleIf: "{total} >= 100",
elements: []
}
]
};
Compare this to the RHF version for a moment.
- The
superRefine
block that conditionally requiredusername
andpassword
is gone.visibleIf: "{hasAccount} = 'Yes'"
combined withisRequired: true
handles both concerns together, on the field itself, where you’d expect to find them. - The
useWatch
+useMemo
chain that computedsubtotal
,tax
, andtotal
is replaced by threeexpression
fields that reference each other by name. - The review page condition, which in the RHF version was reconstructable only by tracing through
showSubmit
, the step 3 render branch. - And finally, the nav button logic is a single
visibleIf
property on the page object.
The same logic is there. It’s just that the schema gives it a place to live where it’s visible in isolation, rather than spread across the component.
Also, note that the schema uses type: 'expression'
for subtotal, tax, and total. Expression is read-only and used mainly to display calculated values. SurveyJS also supports type: 'html'
for static content, but for calculated values, expression
is the right choice.
Now for the React side.
Rendering And Submission
Very simple. Wire onComplete
to your API the same way — via useMutation
or plain fetch
:
import { useState, useEffect, useRef } from "react";
import { useMutation } from "@tanstack/react-query";
import { Model } from "survey-core";
import { Survey } from "survey-react-ui";
import "survey-core/survey-core.css";
export function SurveyForm() {
const [model] = useState(() => new Model(surveySchema));
const mutation = useMutation({
mutationFn: async (data) => {
const res = await fetch("/api/orders", {
method: "POST",
headers: { "Content-Type": "application/json" },
body: JSON.stringify(data),
});
if (!res.ok) throw new Error("Failed to submit");
return res.json();
},
});
const mutationRef = useRef(mutation);
mutationRef.current = mutation;
useEffect(() => {
